class Solution {
public:
    int numOfUnplacedFruits(vector<int>& fruits, vector<int>& baskets) {
        int n = (int)baskets.size();
        int size = 1;
        while (size < n) size *= 2;
        vector<int> tree(2 * size, 0);
        for (int i = 0; i < n; i++) tree[size + i] = baskets[i];
        for (int i = size - 1; i >= 1; i--) tree[i] = max(tree[2 * i], tree[2 * i + 1]);

        int unplaced = 0;
        for (int f : fruits) {
            if (tree[1] < f) {
                unplaced++;
                continue;
            }
            int node = 1;
            while (node < size) {
                if (tree[2 * node] >= f) node = 2 * node;
                else node = 2 * node + 1;
            }
            int pos = node - size;
            tree[node] = 0;
            for (node /= 2; node >= 1; node /= 2) {
                tree[node] = max(tree[2 * node], tree[2 * node + 1]);
            }
        }
        return unplaced;
    }
};
